insert into kb.sections(article_id,version,anchor,heading,body,keywords) values
  ('transfer-timing',1,'main','Pending transfers and due dates','In this demo, DemoBank FAST transfers usually reach the payee within minutes. A transfer that is still pending after one business day needs the bank to check it; this chat cannot see why it is held or when it will complete. Do not send the payment again while the first one is pending, because both payments may go through. If a bill is due soon, contact the bank through its official app or website now, and tell the payee that the payment is delayed. These are synthetic demo terms, not a live bank service standard.','pending transfer transfers fast landlord rent payee delayed arrive resend send again on time'),
  ('account-security-after-fraud',1,'main','Locked out after a suspicious charge','If you report a suspicious card charge and are also locked out of the app, treat the lockout as a possible security issue. This chat cannot tell whether the two are linked. First reset your password in the official app with Forgot password; never use a link in a message, email or call. After you sign in, check for devices or contact details you do not recognise and report them to the bank through the official app. Keep your card blocked until the bank has checked it. Never share your password, PIN or one-time code.','compromised account security hacked suspicious linked related');
insert into kb.articles(article_id,version,title,categories,publisher,scope,kind,status,reference_url,checked_on,review_due) values
  ('unrecognised-charge',2,'Unrecognised card charge',array['fraud'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null),
  ('support',3,'Getting human support',array['retail','fraud','compliance','document','relationship'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null);
insert into kb.sections(article_id,version,anchor,heading,body,keywords) values
  ('unrecognised-charge',2,'urgent-steps','Urgent steps for an unrecognised charge','If you do not recognise a card charge, act now: 1. Contact your bank immediately through the official fraud line printed on the back of your card or the report function in its official app. 2. Ask for the card to be blocked if it may be compromised. 3. Check your other recent transactions. 4. Never share your PIN, password, one-time code or full card number. In this demo the assistant can offer a temporary block of a synthetic card and prepare a dispute draft that lists the charges for bank staff; each runs only after you confirm it. Staff decide any refund or cancellation. The assistant cannot investigate, decide or reverse a charge.','unrecognised unrecognized unfamiliar charge fraud suspicious transaction dont recognise not mine block dispute'),
  ('unrecognised-charge',2,'patterns','Small charges before a larger one','Several small charges from the same merchant shortly before a larger one can be a sign that someone is testing a stolen card number. A pattern like this is a reason to check the charges with the bank, not proof of fraud. Include every charge you do not recognise when you report them.','small charges smaller card testing pattern before weird earlier'),
  ('unrecognised-charge',2,'replacement-card','Replacement card after a block','A temporary block stops new card payments but does not cancel the card or reverse any charge. Identity verification and permanent cancellation are done by bank staff. After staff confirm the card should be cancelled, the bank issues a replacement card with a new number to your registered address.','replacement card new card block cancel cancellation verification'),
  ('support',3,'main','Getting human support','When you are signed in, Talk to a person shows a short summary; approving it records a support handoff for staff in this demo. The demo has no staffed queue, so no person will reply. As a guest you can review, edit and copy a summary for your own use; copying does not send anything. For a real issue, contact your bank using its official app or website. The chatbot cannot make payments, close accounts, refund or reverse charges, or change banking records. A signed-in customer can confirm a dispute draft for a suspicious card charge; staff decide its outcome.','human person support staff contact close dispute transfer refund handoff');
